&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:18px&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Nội thất Slavia hướng đến người l&amp;aacute;i với bố tr&amp;iacute; khoa học, cảm gi&amp;aacute;c rộng r&amp;atilde;i nhờ c&amp;aacute;c đường ngang tr&amp;ecirc;n t&amp;aacute;p l&amp;ocirc;.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li style=&quot;list-style-type:disc&quot;&gt;&lt;span style=&quot;font-size:18px&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Đồng hồ kỹ thuật số Virtual Cockpit 8 inch (Style), TFT 3,5 - 4,2 inch (bản thấp).&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;list-style-type:disc&quot;&gt;&lt;span style=&quot;font-size:18px&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;M&amp;agrave;n h&amp;igrave;nh giải tr&amp;iacute; 7 - 10 inch với kết nối Apple CarPlay v&amp;agrave; Android Auto kh&amp;ocirc;ng d&amp;acirc;y.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;list-style-type:disc&quot;&gt;&lt;span style=&quot;font-size:18px&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Điều h&amp;ograve;a tự động với lọc kh&amp;ocirc;ng kh&amp;iacute; Air Care tr&amp;ecirc;n bản cao.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;list-style-type:disc&quot;&gt;&lt;span style=&quot;font-size:18px&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Ghế ngồi bản cao cấp bọc da, chỉnh điện 6 hướng, c&amp;oacute; l&amp;agrave;m m&amp;aacute;t ghế.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;list-style-type:disc&quot;&gt;&lt;span style=&quot;font-size:18px&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;H&amp;agrave;ng ghế sau c&amp;oacute; thể gập theo tỉ lệ 60:40, t&amp;iacute;ch hợp tựa tay trung t&amp;acirc;m với gi&amp;aacute; để cốc (phi&amp;ecirc;n bản Style), c&amp;ugrave;ng cửa gi&amp;oacute; điều h&amp;ograve;a ri&amp;ecirc;ng biệt. Tạo kh&amp;ocirc;ng gian cho khoang h&amp;agrave;nh l&amp;yacute;.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:18px&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Về khả năng chứa đồ, khoang h&amp;agrave;nh l&amp;yacute; của Slavia đạt 521 l&amp;iacute;t, lớn nhất ph&amp;acirc;n kh&amp;uacute;c sedan hạng B. Khi cần th&amp;ecirc;m kh&amp;ocirc;ng gian, người d&amp;ugrave;ng c&amp;oacute; thể gập phẳng h&amp;agrave;ng ghế sau để mở rộng dung t&amp;iacute;ch l&amp;ecirc;n đến 1.050 l&amp;iacute;t, đủ để chứa h&amp;agrave;nh l&amp;yacute; cho những chuyến đi xa của cả gia đ&amp;igrave;nh.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

