&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:18px&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;Skoda Slavia 2025 an to&amp;agrave;n v&amp;agrave; c&amp;ocirc;ng nghệ hỗ trợ&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:18px&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Skoda trang bị cho Slavia 2025 đầy đủ c&amp;aacute;c t&amp;iacute;nh năng an to&amp;agrave;n chủ động v&amp;agrave; bị động:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li style=&quot;list-style-type:disc&quot;&gt;&lt;span style=&quot;font-size:18px&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;6 t&amp;uacute;i kh&amp;iacute;, ABS/EBD/BA, ESC, hỗ trợ khởi h&amp;agrave;nh ngang dốc, kiểm so&amp;aacute;t lực k&amp;eacute;o.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;list-style-type:disc&quot;&gt;&lt;span style=&quot;font-size:18px&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Cảnh b&amp;aacute;o điểm m&amp;ugrave;, hỗ trợ phanh khẩn cấp ph&amp;iacute;a trước, cảnh b&amp;aacute;o phương tiện cắt ngang ph&amp;iacute;a sau.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;list-style-type:disc&quot;&gt;&lt;span style=&quot;font-size:18px&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;Camera l&amp;ugrave;i, cảm biến l&amp;ugrave;i, điều khiển h&amp;agrave;nh tr&amp;igrave;nh, kh&amp;oacute;a vi sai điện tử.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

