	&lt;/li&gt;
	&lt;li&gt;
	&lt;p style=&quot;font-size: 18px; line-height: 1.5rem; text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:18px;&quot;&gt;&lt;span style=&quot;line-height:1.5;&quot;&gt;Lưỡi gạt bị nứt, chai cứng, bong tróc. &lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
