	&lt;p style=&quot;font-size: 18px; line-height: 1.5rem; margin-bottom: 1rem; text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:18px;&quot;&gt;Tùy chọn sơn ngoại thất màu Đỏ Dynamic hoặc Xanh Holborn &lt;/span&gt;&lt;/p&gt;
	&lt;/li&gt;
	&lt;li style=&quot;margin-bottom:0.5rem;line-height:1.5;&quot;&gt;
