&lt;h3 style=&quot;line-height: 1.8; margin-top: 21px; margin-bottom: 5px; text-align: justify;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size:22px;&quot;&gt;&lt;span style=&quot;font-variant: normal; white-space: pre-wrap;&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#434343&quot;&gt;&lt;span style=&quot;font-weight:700&quot;&gt;&lt;span style=&quot;font-style:normal&quot;&gt;&lt;span style=&quot;text-decoration:none&quot;&gt;3.2 Khung thép đàn hồi &amp; thiết kế khí động học&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;

&lt;p style=&quot;line-height: 1.8; text-align: justify;&quot;&gt;&lt;span style=&quot;font-size:18px;&quot;&gt;&lt;span style=&quot;font-variant: normal; white-space: pre-wrap;&quot;&gt;&lt;span style=&quot;font-family:&#039;Times New Roman&#039;,serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-weight:400&quot;&gt;&lt;span style=&quot;font-style:normal&quot;&gt;&lt;span style=&quot;text-decoration:none&quot;&gt;Khung gạt mưa silicon thường sử dụng thép đàn hồi cao, phân bổ lực đều trên toàn bộ lưỡi gạt. Thiết kế khí động học giúp gạt mưa bám kính tốt hơn khi xe chạy tốc độ cao, không bị rung hay bật gió.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

